begin;
set local lock_timeout='5s';set local statement_timeout='60s';
create table public.property_contract_versions(id uuid primary key default gen_random_uuid(),contract_key text not null unique,source_file text not null,source_sha256 text not null,definition jsonb not null,new_assignment_enabled boolean not null default false);
create table public.property_category_contracts(category_id uuid not null references public.categories(id),version_id uuid not null references public.property_contract_versions(id),source_path jsonb not null,fields jsonb not null,source_provenance jsonb not null,definition jsonb not null,display_order integer not null,primary key(category_id,version_id));
create table public.listing_property_contexts(listing_id uuid primary key references public.listings(id) on delete cascade,category_id uuid not null,version_id uuid not null,financial jsonb not null,society_name text,foreign key(category_id,version_id) references public.property_category_contracts(category_id,version_id));
alter table public.property_contract_versions enable row level security;
alter table public.property_category_contracts enable row level security;
alter table public.listing_property_contexts enable row level security;
revoke all on public.property_contract_versions,public.property_category_contracts,public.listing_property_contexts from public,anon,authenticated,service_role;
grant select on public.property_contract_versions,public.property_category_contracts to authenticated;
create policy property_versions_read on public.property_contract_versions for select to authenticated using(true);
create policy property_contracts_read on public.property_category_contracts for select to authenticated using(true);
grant select,insert,update on public.listing_property_contexts to authenticated;
create policy property_context_read on public.listing_property_contexts for select to authenticated using(exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid())));
create policy property_context_insert on public.listing_property_contexts for insert to authenticated with check(exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft') and app_security.get_account_status((select auth.uid()))::text='active' and app_security.has_current_policy_acceptance((select auth.uid())));
create policy property_context_update on public.listing_property_contexts for update to authenticated using(exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft') and app_security.get_account_status((select auth.uid()))::text='active' and app_security.has_current_policy_acceptance((select auth.uid()))) with check(exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft') and app_security.get_account_status((select auth.uid()))::text='active' and app_security.has_current_policy_acceptance((select auth.uid())));
create function app_security.property_amount(a jsonb,positive boolean) returns void language plpgsql set search_path='' as $$
begin
 if a is null or jsonb_typeof(a)<>'object' or a->>'state' is null then raise exception using errcode='22023',message='Complete the amount declaration'; end if;
 if a->>'state' in ('unanswered','unknown') then
  if a<>jsonb_build_object('state',a->>'state') then raise exception using errcode='22023',message='Unknown/unanswered amount cannot carry a value'; end if;
 elsif a->>'state'='known' then
  if a- 'state'-'amount_paise'<>'{}' or jsonb_typeof(a->'amount_paise') is distinct from 'number' or (a->>'amount_paise')::numeric<>trunc((a->>'amount_paise')::numeric) or (a->>'amount_paise')::numeric<(case when positive then 1 else 0 end) or (a->>'amount_paise')::numeric>9007199254740991 then raise exception using errcode='22023',message='Known amount requires whole safe paise; rent must be positive'; end if;
 else raise exception using errcode='22023',message='Unsupported amount state'; end if;
end $$;

create function app_security.validate_property_components(a jsonb,f jsonb,s text,p jsonb) returns void language plpgsql set search_path='' as $$
declare k text;val jsonb;n numeric;fields jsonb:=p->'fields';expected text:=p->>'basis';dt date;
begin
 if a is null or jsonb_typeof(a)<>'object' or f is null or jsonb_typeof(f)<>'object' then raise exception using errcode='22023',message='Property answers/financial declarations must be objects'; end if;
 for k,val in select * from jsonb_each(a) loop
  if not fields ? k and not(k='area_basis' and fields ? 'area_sqft') then raise exception using errcode='22023',message=k||' does not apply to this category'; end if;
  if k in ('monthly_rent','monthly_rent_per_bed','security_deposit','maintenance','city','locality','society_name') then raise exception using errcode='22023',message='Duplicate financial/location/private attributes are forbidden'; end if;
  if k in ('bhk','bathrooms','floors','total_floors','floor','area_sqft') then
   if jsonb_typeof(val)<>'number' then raise exception using errcode='22023',message='Property numeric answers must be numbers'; end if;
   n:=(val#>>'{}')::numeric;
   if k='area_sqft' then
    if n<=0 or n>1000000000 or n*100<>trunc(n*100) then raise exception using errcode='22023',message='Area is positive square feet with at most two decimals'; end if;
   elsif k='floor' then
    if n<>trunc(n) or n not between -1000 and 1000 then raise exception using errcode='22023',message='Floor is a signed whole level label'; end if;
   elsif n<>trunc(n) or n not between 0 and 10000 or (k in ('floors','total_floors') and n=0) then raise exception using errcode='22023',message='Invalid whole Property count'; end if;
  elsif k in ('attached_bathroom','food_included','ac','wifi','housekeeping','parking') then
   if jsonb_typeof(val)<>'string' or val#>>'{}' not in ('unanswered','yes','no') then raise exception using errcode='22023',message='Amenity requires explicit unanswered/yes/no'; end if;
  elsif k='available_from' then
   if jsonb_typeof(val)<>'string' or val#>>'{}' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception using errcode='22023',message='Enter an actual calendar date'; end if;
   begin dt:=(val#>>'{}')::date; exception when others then raise exception using errcode='22023',message='Enter an actual calendar date'; end;
   if to_char(dt,'YYYY-MM-DD')<>val#>>'{}' then raise exception using errcode='22023',message='Enter an actual calendar date'; end if;
  elsif k='area_basis' then
   if jsonb_typeof(val)<>'string' or val#>>'{}' not in ('unspecified','carpet','built_up','super_built_up') then raise exception using errcode='22023',message='Unsupported area-basis declaration'; end if;
  elsif k in ('furnishing','preferred_tenants','sharing_type','gender','gender_preference') then
   if jsonb_typeof(val)<>'string' or length(trim(val#>>'{}')) not between 1 and 200 then raise exception using errcode='22023',message='Seller text must be 1–200 characters'; end if;
  else raise exception using errcode='22023',message='Unsupported Property answer'; end if;
 end loop;
 if f-'currency'-'period'-'basis'-'rent'-'deposit'-'maintenance'<>'{}' or f->>'currency' is distinct from 'INR' or f->>'period' is distinct from 'month' then raise exception using errcode='22023',message='Property requires monthly INR declarations only'; end if;
 if expected is not null then
  if f->>'basis' is distinct from expected then raise exception using errcode='22023',message='Rental basis does not match category'; end if;
 elsif f ? 'basis' and (jsonb_typeof(f->'basis')<>'string' or f->>'basis' not in ('advertised_room','occupant_share')) then raise exception using errcode='22023',message='Select room or occupant-share basis'; end if;
 perform app_security.property_amount(f->'rent',true);
 if f->'rent'->>'state'='known' and f->>'basis' is null then raise exception using errcode='22023',message='Known rent requires an explicit rental basis'; end if;
 if f ? 'deposit' then
  if not fields ? 'security_deposit' then raise exception using errcode='22023',message='Deposit does not apply'; end if;
  perform app_security.property_amount(f->'deposit',false);
 end if;
 if f ? 'maintenance' then
  if not fields ? 'maintenance' or jsonb_typeof(f->'maintenance')<>'object' then raise exception using errcode='22023',message='Maintenance does not apply or is incomplete'; end if;
  if f->'maintenance'->>'state'='separate' then
   if (f->'maintenance')-'state'-'amount_paise'-'basis'-'period'<>'{}' or f->'maintenance'->>'period' is distinct from 'month' or f->'maintenance'->>'basis' is distinct from f->>'basis' or f->'maintenance'->>'basis' is null then raise exception using errcode='22023',message='Separate maintenance needs an explicit matching monthly basis'; end if;
   perform app_security.property_amount(jsonb_build_object('state','known','amount_paise',f->'maintenance'->'amount_paise'),true);
  elsif f->'maintenance'->>'state' in ('unanswered','unknown','included_in_rent','none') then
   if f->'maintenance'<>jsonb_build_object('state',f->'maintenance'->>'state') then raise exception using errcode='22023',message='Nonseparate maintenance cannot carry charges'; end if;
  else raise exception using errcode='22023',message='Unsupported maintenance state'; end if;
 end if;
 if s is not null and (not fields ? 'society_name' or length(trim(s)) not between 1 and 200) then raise exception using errcode='22023',message='Society name is bounded private text on applicable paths'; end if;
end $$;

create function app_security.property_context_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare l public.listings%rowtype;p public.property_category_contracts%rowtype;v public.property_contract_versions%rowtype;c public.categories%rowtype;retained boolean:=false;
begin
 select * into l from public.listings where id=new.listing_id;
 if not found or auth.uid() is null or l.seller_id<>auth.uid() or l.status<>'draft' or app_security.get_account_status(auth.uid())::text<>'active' or not app_security.has_current_policy_acceptance(auth.uid()) then raise exception using errcode='42501',message='Owned Property draft required'; end if;
 retained:=exists(select 1 from public.listing_property_contexts x where x.listing_id=new.listing_id and x.category_id=new.category_id and x.version_id=new.version_id);
 if tg_op='UPDATE' then
  if new.listing_id<>old.listing_id then raise exception using errcode='22023',message='Property context listing is immutable'; end if;
  retained:=new.category_id=old.category_id and new.version_id=old.version_id;
 end if;
 select * into p from public.property_category_contracts where category_id=new.category_id and version_id=new.version_id;
 if not found or l.category_id<>new.category_id then raise exception using errcode='22023',message='Property category/version reference unavailable'; end if;
 select * into v from public.property_contract_versions where id=new.version_id;
 select * into c from public.categories where id=new.category_id;
 if not retained and (not c.is_active or not c.new_listing_enabled or not v.new_assignment_enabled) then raise exception using errcode='22023',message='Property category closed to new assignment'; end if;
 perform app_security.validate_property_components(l.category_attributes,new.financial,new.society_name,p.definition);
 return new;
end $$;

create function app_security.property_listing_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.property_category_contracts where category_id=new.category_id) or exists(select 1 from public.listing_property_contexts where listing_id=new.id) then
  if not exists(select 1 from public.property_category_contracts where category_id=new.category_id) then raise exception using errcode='22023',message='Property draft must retain a Property category'; end if;
  if new.status<>'draft' then raise exception using errcode='22023',message='Property review/publication disabled'; end if;
  if new.price_paise is not null or new.price_type is not null or new.condition is not null then raise exception using errcode='22023',message='Property item price/type/condition must be NULL'; end if;
 end if;
 return new;
end $$;

create function app_security.property_context_complete() returns trigger language plpgsql security definer set search_path='' as $$
declare lid uuid;l public.listings%rowtype;x public.listing_property_contexts%rowtype;p public.property_category_contracts%rowtype;
begin
 if tg_table_name='listings' then lid:=new.id;else lid:=new.listing_id;end if;
 select * into l from public.listings where id=lid;
 if exists(select 1 from public.property_category_contracts where category_id=l.category_id) then
  select * into x from public.listing_property_contexts where listing_id=lid and category_id=l.category_id;
  if not found then raise exception using errcode='22023',message='Property draft requires its matching context'; end if;
  select * into p from public.property_category_contracts where category_id=x.category_id and version_id=x.version_id;
  if not found then raise exception using errcode='22023',message='Property category/version reference unavailable'; end if;
  perform app_security.validate_property_components(l.category_attributes,x.financial,x.society_name,p.definition);
 end if;
 return null;
end $$;

create function public.save_property_draft(p_listing_id uuid,p_listing jsonb,p_version_id uuid,p_financial jsonb,p_society_name text) returns uuid language plpgsql security invoker set search_path='' as $$
declare lid uuid;p public.property_category_contracts%rowtype;l public.listings%rowtype;cid uuid;
begin
 if auth.uid() is null or app_security.get_account_status(auth.uid())::text<>'active' or not app_security.has_current_policy_acceptance(auth.uid()) then raise exception using errcode='42501',message='Active policy-approved owner required'; end if;
 if p_listing is null or jsonb_typeof(p_listing)<>'object' or p_listing-'title'-'category_id'-'city_id'-'locality_id'-'description'-'condition'-'price_type'-'price_paise'-'pin_code'-'landmark'-'category_attributes'<>'{}' then raise exception using errcode='22023',message='Unexpected Property draft metadata'; end if;
 if p_listing->>'price_paise' is not null or p_listing->>'price_type' is not null or p_listing->>'condition' is not null then raise exception using errcode='22023',message='Property item price/type/condition must be NULL'; end if;
 begin cid:=(p_listing->>'category_id')::uuid; exception when invalid_text_representation then raise exception using errcode='22023',message='Property category reference unavailable'; end;
 select * into p from public.property_category_contracts where category_id=cid and version_id=p_version_id;
 if not found then raise exception using errcode='22023',message='Property category/version reference unavailable'; end if;
 if p_listing_id is not null then
  select * into l from public.listings where id=p_listing_id and seller_id=auth.uid() and status='draft' for update;
  if not found or not exists(select 1 from public.listing_property_contexts where listing_id=p_listing_id) then raise exception using errcode='42501',message='Owned Property draft required'; end if;
  lid:=p_listing_id;
  update public.listings set title=p_listing->>'title',category_id=cid,city_id=(p_listing->>'city_id')::uuid,locality_id=(p_listing->>'locality_id')::uuid,description=p_listing->>'description',condition=null,price_type=null,price_paise=null,pin_code=p_listing->>'pin_code',landmark=p_listing->>'landmark',category_attributes=coalesce(p_listing->'category_attributes','{}') where id=lid;
 else
  insert into public.listings(title,category_id,city_id,locality_id,description,condition,price_type,price_paise,pin_code,landmark,category_attributes) values(p_listing->>'title',cid,(p_listing->>'city_id')::uuid,(p_listing->>'locality_id')::uuid,p_listing->>'description',null,null,null,p_listing->>'pin_code',p_listing->>'landmark',coalesce(p_listing->'category_attributes','{}')) returning id into lid;
 end if;
 insert into public.listing_property_contexts(listing_id,category_id,version_id,financial,society_name) values(lid,cid,p_version_id,p_financial,p_society_name) on conflict(listing_id) do update set category_id=excluded.category_id,version_id=excluded.version_id,financial=excluded.financial,society_name=excluded.society_name;
 return lid;
end $$;

create trigger property_context_guard before insert or update on public.listing_property_contexts for each row execute function app_security.property_context_guard();
create trigger zzz_property_listing_guard before insert or update on public.listings for each row execute function app_security.property_listing_guard();
create constraint trigger property_listing_context_complete after insert or update on public.listings deferrable initially deferred for each row execute function app_security.property_context_complete();
create constraint trigger property_context_listing_complete after insert or update on public.listing_property_contexts deferrable initially deferred for each row execute function app_security.property_context_complete();
revoke all on function app_security.property_amount(jsonb,boolean),app_security.validate_property_components(jsonb,jsonb,text,jsonb),app_security.property_context_guard(),app_security.property_listing_guard(),app_security.property_context_complete() from public,anon,authenticated,service_role;
revoke all on function public.save_property_draft(uuid,jsonb,uuid,jsonb,text) from public,anon,authenticated,service_role;
grant execute on function public.save_property_draft(uuid,jsonb,uuid,jsonb,text) to authenticated;
